// Ingest Lambda header validation (pseudo)
function validHeader(csv){ 
  const exp = ['id','name','amount','date'];
  const head = csv.split('\n')[0].split(',').map(x=>x.trim());
  return exp.every((v,i)=> head[i]===v);
}
